const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var palmSprings = ee.Geometry.Point(-116.5453, 33.8303).buffer(1000); // 1km buffer
  var startDate2017 = '2017-07-15';
  var endDate2017 = '2017-07-22'; // exclusive
  var startYear = 2001;
  var endYear = 2010;

  // 2. Data Acquisition
  var modisCol = ee.ImageCollection('MODIS/006/MOD11A2')
    .select(['LST_Day_1km', 'QC_Day']);

  // Function to apply quality mask
  function applyQAMask(image) {
    var qa = image.select('QC_Day');
    // Bits 0-1: Mandatory QA flags (0=good, 1=other quality)
    var mask = qa.bitwiseAnd(3).eq(0); // Keep only good quality
    return image.updateMask(mask);
  }

  // Function to get mean LST for a given date range
  function getMeanLST(start, end) {
    var col = modisCol.filterDate(start, end)
                      .filterBounds(palmSprings)
                      .map(applyQAMask);
    var count = col.size();
    // If no images, return null
    if (count.getInfo() === 0) {
      return {mean: null, pixelCount: 0, imgCount: 0};
    }
    // Compute mean image over the period
    var meanImg = col.mean();
    // Convert LST from Kelvin*0.02 to Celsius
    var lstC = meanImg.select('LST_Day_1km').multiply(0.02).subtract(273.15);
    // Get pixel count and mean value
    var stats = lstC.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: palmSprings,
      scale: 1000,
      maxPixels: 1e9,
    });
    var meanVal = stats.get('LST_Day_1km_mean');
    var pixelCount = stats.get('LST_Day_1km_count');
    return {mean: meanVal, pixelCount: pixelCount, imgCount: count};
  }

  // 3. Get 2017 data
  var lst2017 = getMeanLST(startDate2017, endDate2017);
  var imgCount2017 = lst2017.imgCount;
  var pixelCount2017 = lst2017.pixelCount;
  var mean2017 = lst2017.mean;

  // Check for no data or no valid pixels
  if (imgCount2017.getInfo() === 0) {
    console.log('2017 Images: 0');
    console.log('<answer>C1</answer>');
    return;
  }
  if (pixelCount2017.getInfo() === 0) {
    console.log('2017 Images: ' + imgCount2017.getInfo() + ' (Val: 0 pixels)');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Get 2001-2010 yearly means
  var yearlyMeans = [];
  var yearlyCounts = [];
  for (var year = startYear; year <= endYear; year++) {
    var start = year + '-07-15';
    var end = year + '-07-22';
    var lstYear = getMeanLST(start, end);
    var imgCount = lstYear.imgCount;
    var pixelCount = lstYear.pixelCount;
    var meanVal = lstYear.mean;
    yearlyCounts.push(imgCount);
    if (imgCount.getInfo() === 0) {
      console.log(year + ' Images: 0');
      console.log('<answer>C1</answer>');
      return;
    }
    if (pixelCount.getInfo() === 0) {
      console.log(year + ' Images: ' + imgCount.getInfo() + ' (Val: 0 pixels)');
      console.log('<answer>C2</answer>');
      return;
    }
    yearlyMeans.push(meanVal);
  }

  // Compute average of yearly means
  var avgHist = ee.List(yearlyMeans).reduce(ee.Reducer.mean());

  // 5. Get values
  var mean2017Val = mean2017.getInfo();
  var avgHistVal = avgHist.getInfo();

  // 6. Validation
  if (mean2017Val === null || avgHistVal === null || 
      isNaN(mean2017Val) || isNaN(avgHistVal)) {
    console.log('2017 Mean: ' + mean2017Val + ', Historical Avg: ' + avgHistVal);
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for unrealistic values (outside typical LST range for desert in July)
  // Palm Springs July average high ~42°C, but LST can be higher. Let's set bounds -20 to 80°C.
  if (mean2017Val < -20 || mean2017Val > 80 || avgHistVal < -20 || avgHistVal > 80) {
    console.log('2017 Mean: ' + mean2017Val.toFixed(2) + '°C, Historical Avg: ' + avgHistVal.toFixed(2) + '°C');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Output stats and answer
  console.log('2017 Images: ' + imgCount2017.getInfo() + ' (Val: ' + pixelCount2017.getInfo() + ' pixels)');
  console.log('2001-2010 Images per year: ' + yearlyCounts.map(c => c.getInfo()).join(','));
  console.log('2017 Mean LST: ' + mean2017Val.toFixed(2) + '°C');
  console.log('2001-2010 Avg LST: ' + avgHistVal.toFixed(2) + '°C');

  if (mean2017Val > avgHistVal) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
